mu0 noncomputable def mu0 (I : Instance) (ε δ : ℚ) : PMF (Finset ℕ) *A fresh `μ₀` draw** (`algorithm.tex:215-224`): per small cell `s`, `k_s` by a dyadic draw from `{0..b_s}`, then a `k_s`-subset of its `b_s` pairs by a dyadic draw of a rank in `[0, C(b_s, k_s))`; those pairs use their row element, the rest their column element. noncomputable def mu0 (I : Instance) (ε δ : ℚ) : PMF (Finset ℕ) :=
  loop (fun s S => do
    let k ← dyadicDraw (smallB I ε δ s + 1) (ξParam I ε δ)
    let rank ← dyadicDraw (Nat.choose (smallB I ε δ s) k) (ξParam I ε δ)
    pure (S ∪ (Finset.range (smallB I ε δ s)).image fun t =>
      if t ∈ unrank (smallB I ε δ s) k rank then 2 * (cellFirst I ε δ s + t)
      else 2 * (cellFirst I ε δ s + t) + 1))
    (nSmall I ε δ) ∅

